result=[]
for typ in sorted({p['product_type'] for p in catalog}):
 handle=mapping.get(typ);collection=registry.get(handle)
 result.append({'product_type':typ,'articles':sum(p['product_type']==typ for p in catalog),'proposed_collection':collection,'status':'VOORSTEL_BESTAANDE_COLLECTIE' if collection else 'BESTEMMING_CONTROLEREN','applied':False,'guard':'Existing collection identity verified; membership rules and additive assignment still require pre-import review.'})
(root/'collection-proposals.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'types':len(result),'existing_identity_proposals':sum(r['proposed_collection'] is not None for r in result),'unresolved':[r['product_type'] for r in result if not r['proposed_collection']]}))
